import numpy as np


def construct(budget_seconds, start):
    """Code Zero: keep the start if there is one, otherwise 26 small equal circles on a grid."""
    if start is not None:
        return np.asarray(start, dtype=float)
    k = int(np.ceil(np.sqrt(26)))
    pts = [((i + 0.5) / k, (j + 0.5) / k) for j in range(k) for i in range(k)][:26]
    return np.array([[x, y, 0.02] for x, y in pts])

import numpy as np
import time
from scipy.optimize import minimize


def _project(xyr, n):
    x = xyr[:, 0]; y = xyr[:, 1]; r = xyr[:, 2]
    box = np.minimum(np.minimum(x, 1 - x), np.minimum(y, 1 - y))
    with np.errstate(divide='ignore', invalid='ignore'):
        t = 1.0
        for i in range(n):
            dx = x[i] - x; dy = y[i] - y
            d = np.sqrt(dx * dx + dy * dy)
            s = r[i] + r
            s[i] = 1e300
            ratio = d / s
            ratio[i] = 1e300
            m = ratio.min()
            if m < t:
                t = m
        tb = (box / r).min() if np.all(r > 0) else 0.0
        if tb < t:
            t = tb
    return max(t, 0.0)


def _score_of(a, n):
    a = a.copy()
    a[:, 0] = np.clip(a[:, 0], 1e-6, 1 - 1e-6)
    a[:, 1] = np.clip(a[:, 1], 1e-6, 1 - 1e-6)
    a[:, 2] = np.maximum(a[:, 2], 1e-6)
    t = _project(a, n)
    a[:, 2] *= t
    return a, a[:, 2].sum()


def _make_initial(n, rng):
    best = None; best_score = -1
    for _ in range(8):
        pts = []
        rows = int(np.ceil(np.sqrt(n)))
        cols = int(np.ceil(n / rows))
        for j in range(rows + 2):
            for i in range(cols + 2):
                x = (i + 0.5 + 0.5 * (j % 2)) / (cols + 1)
                y = (j + 0.5) / (rows + 1)
                if 0 < x < 1 and 0 < y < 1:
                    pts.append((x, y))
        pts = pts[:n]
        while len(pts) < n:
            pts.append((rng.random(), rng.random()))
        arr = np.zeros((n, 3))
        arr[:, 0] = [p[0] for p in pts]
        arr[:, 1] = [p[1] for p in pts]
        arr[:, 2] = 0.05
        arr[:, 0] = np.clip(arr[:, 0] + rng.normal(0, 0.01, n), 0.01, 0.99)
        arr[:, 1] = np.clip(arr[:, 1] + rng.normal(0, 0.01, n), 0.01, 0.99)
        t = _project(arr, n)
        arr[:, 2] = 0.05 * t
        s = arr[:, 2].sum()
        if s > best_score:
            best_score = s; best = arr
    return best


def _active_set_slsqp(xyr, n, maxiter=300):
    x0 = xyr.copy()

    def unpack(v):
        return v.reshape(n, 3)

    def objective(v):
        return -v[2::3].sum()

    def objective_grad(v):
        g = np.zeros_like(v)
        g[2::3] = -1.0
        return g

    x = x0[:, 0]; y = x0[:, 1]; r = x0[:, 2]
    margin = 1e-3
    active_walls = []
    for i in range(n):
        if x[i] - r[i] < margin: active_walls.append((i, 0))
        if 1 - x[i] - r[i] < margin: active_walls.append((i, 1))
        if y[i] - r[i] < margin: active_walls.append((i, 2))
        if 1 - y[i] - r[i] < margin: active_walls.append((i, 3))
    active_pairs = []
    for i in range(n):
        for j in range(i + 1, n):
            d = np.hypot(x[i] - x[j], y[i] - y[j])
            if d - (r[i] + r[j]) < margin:
                active_pairs.append((i, j))

    def make_cons(walls, pairs):
        def cons(v):
            a = unpack(v)
            xx = a[:, 0]; yy = a[:, 1]; rr = a[:, 2]
            out = []
            for (i, k) in walls:
                if k == 0: out.append(xx[i] - rr[i])
                elif k == 1: out.append(1 - xx[i] - rr[i])
                elif k == 2: out.append(yy[i] - rr[i])
                else: out.append(1 - yy[i] - rr[i])
            for (i, j) in pairs:
                d = np.sqrt((xx[i] - xx[j]) ** 2 + (yy[i] - yy[j]) ** 2 + 1e-30)
                out.append(d - rr[i] - rr[j])
            return np.array(out) if out else np.zeros(0)

        def jac(v):
            a = unpack(v)
            xx = a[:, 0]; yy = a[:, 1]; rr = a[:, 2]
            rows = []
            for (i, k) in walls:
                row = np.zeros(3 * n)
                if k == 0: row[3*i] = 1.0; row[3*i+2] = -1.0
                elif k == 1: row[3*i] = -1.0; row[3*i+2] = -1.0
                elif k == 2: row[3*i+1] = 1.0; row[3*i+2] = -1.0
                else: row[3*i+1] = -1.0; row[3*i+2] = -1.0
                rows.append(row)
            for (i, j) in pairs:
                dx = xx[i] - xx[j]; dy = yy[i] - yy[j]
                d = np.sqrt(dx*dx + dy*dy + 1e-30)
                row = np.zeros(3 * n)
                row[3*i] = dx/d; row[3*i+1] = dy/d; row[3*i+2] = -1.0
                row[3*j] = -dx/d; row[3*j+1] = -dy/d; row[3*j+2] = -1.0
                rows.append(row)
            return np.array(rows) if rows else np.zeros((0, 3*n))
        return cons, jac

    bounds = [(0, 1)] * (2 * n) + [(1e-6, 0.5)] * n
    cur = x0.copy()
    for _ in range(25):
        cons, jac = make_cons(active_walls, active_pairs)
        try:
            res = minimize(objective, cur.ravel(), jac=objective_grad,
                           method='SLSQP', bounds=bounds,
                           constraints=[{'type': 'ineq', 'fun': cons, 'jac': jac}],
                           options={'maxiter': maxiter, 'ftol': 1e-12})
            cand = unpack(res.x)
        except Exception:
            break
        cx = cand[:, 0]; cy = cand[:, 1]; cr = cand[:, 2]
        added = False
        wall_set = set(active_walls); pair_set = set(active_pairs)
        for i in range(n):
            if cx[i] - cr[i] < -1e-7 and (i, 0) not in wall_set:
                active_walls.append((i, 0)); added = True
            if 1 - cx[i] - cr[i] < -1e-7 and (i, 1) not in wall_set:
                active_walls.append((i, 1)); added = True
            if cy[i] - cr[i] < -1e-7 and (i, 2) not in wall_set:
                active_walls.append((i, 2)); added = True
            if 1 - cy[i] - cr[i] < -1e-7 and (i, 3) not in wall_set:
                active_walls.append((i, 3)); added = True
        for i in range(n):
            for j in range(i + 1, n):
                d = np.hypot(cx[i] - cx[j], cy[i] - cy[j])
                if d - (cr[i] + cr[j]) < -1e-7 and (i, j) not in pair_set:
                    active_pairs.append((i, j)); added = True
        cur = cand
        if not added:
            break
    return cur


def _sa(xyr, n, deadline, rng, T0=2e-3, T1=5e-8, sigma0=0.04):
    """SA on centers + radii jointly, with projection."""
    cur = xyr.copy()
    cur, cur_score = _score_of(cur, n)
    best = cur.copy(); best_score = cur_score
    t_start = time.process_time()
    total = max(deadline - t_start, 1e-6)
    while True:
        now = time.process_time()
        if now >= deadline:
            break
        frac = min((now - t_start) / total, 1.0)
        sigma = sigma0 * np.exp(-3.5 * frac)
        T = T0 * (T1 / T0) ** frac
        i = rng.integers(0, n)
        old = cur[i].copy()
        # alternate between position and radius moves
        if rng.random() < 0.5:
            cur[i, 0] = np.clip(cur[i, 0] + rng.normal(0, sigma), 1e-6, 1-1e-6)
            cur[i, 1] = np.clip(cur[i, 1] + rng.normal(0, sigma), 1e-6, 1-1e-6)
        else:
            cur[i, 2] = max(cur[i, 2] + rng.normal(0, sigma * 0.5), 1e-6)
        cand, s = _score_of(cur, n)
        delta = s - cur_score
        if delta >= 0 or (T > 0 and rng.random() < np.exp(delta / T)):
            cur = cand; cur_score = s
            if s > best_score:
                best_score = s; best = cand.copy()
        else:
            cur[i] = old
    return best, best_score


def construct(budget_seconds, start):
    n = 26
    t0 = time.process_time()
    deadline = budget_seconds - max(0.6, budget_seconds * 0.06)
    rng = np.random.default_rng(987654321)

    best_arr = None; best_score = -1.0
    if start is not None:
        s = np.asarray(start, dtype=float).copy()
        if s.shape == (n, 3):
            a, sc = _score_of(s, n)
            best_arr = a; best_score = sc

    init = _make_initial(n, rng)
    a, sc = _score_of(init, n)
    if sc > best_score:
        best_arr = a; best_score = sc

    # Phase 1: SA (joint radii+positions) -- ~45% budget
    sa_deadline = t0 + (deadline - t0) * 0.45
    arr, sc = _sa(best_arr, n, sa_deadline, rng)
    if sc > best_score:
        best_arr = arr; best_score = sc

    # Phase 2: SLSQP polish from multiple perturbations
    idx = 0
    while True:
        now = time.process_time()
        if deadline - now < 0.4:
            break
        if idx == 0:
            cur = best_arr.copy()
        else:
            base = best_arr.copy()
            scale = 0.005 + 0.015 * rng.random()
            base[:, 0] = np.clip(base[:, 0] + rng.normal(0, scale, n), 0.005, 0.995)
            base[:, 1] = np.clip(base[:, 1] + rng.normal(0, scale, n), 0.005, 0.995)
            # also perturb radii slightly
            base[:, 2] *= (1.0 + rng.normal(0, scale, n))
            base[:, 2] = np.maximum(base[:, 2], 1e-6)
            base, _ = _score_of(base, n)
            cur = base
        try:
            fit = _active_set_slsqp(cur, n, maxiter=200)
            fit, s = _score_of(fit, n)
            if s > best_score:
                best_score = s; best_arr = fit
        except Exception:
            pass
        idx += 1

    # Phase 3: if time remains, short SA from best to escape local opt
    now = time.process_time()
    if deadline - now > 0.5:
        arr, sc = _sa(best_arr, n, deadline - 0.2, rng, T0=5e-4, sigma0=0.015)
        arr, sc = _score_of(arr, n)
        if sc > best_score:
            best_arr = arr; best_score = sc

    a = best_arr.copy()
    a, _ = _score_of(a, n)
    # exact-safe shrink: ensure strict feasibility with margin
    a[:, 2] *= (1.0 - 1e-9)
    a[:, 2] = np.maximum(a[:, 2], 1e-9)
    # final safety re-projection
    t = _project(a, n)
    if t < 1.0:
        a[:, 2] *= t * (1.0 - 1e-12)
    return a
